def p(rel): return os.path.join(HERE, *rel.split("/"))

def main():
    idx = p("index.html")
    if not os.path.exists(idx):
        print("❌ index.html이 없어요. C:\\knexm-site 폴더 안에서 실행해 주세요"); sys.exit(1)
    if "assets/logo-h.svg" in open(idx, encoding="utf-8").read():
        print("이미 적용돼 있어요"); return
    out = {}
    ok = True
    for rel, pairs in EDITS.items():
        raw = open(p(rel), "rb").read().decode("utf-8")
        crlf = "\r\n" in raw
        text = raw.replace("\r\n", "\n")
        for old, new in pairs:
            n = text.count(old)
            if n == 0 or (n > 1 and rel != "sitemap.xml"):
                print("❌", rel, "에서 바꿀 곳을 못 찾았어요:", old[:50]); ok = False; continue
            text = text.replace(old, new)
            print("✔", rel)
        out[rel] = text.replace("\n", "\r\n") if crlf else text
    if not ok:
        print(); print("아무것도 저장하지 않았어요"); sys.exit(1)
    for rel, text in out.items():
        open(p(rel), "wb").write(text.encode("utf-8"))
    for rel, (kind, body) in NEW.items():
        data = base64.b64decode(body) if kind == "b64" else body.encode("utf-8")
        open(p(rel), "wb").write(data)
        print("✔", rel, "(새 파일)")
    print(); print("완료: 로고를 넣었어요")

if __name__ == "__main__":
    main()
